<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue';import { ElMessage } from 'element-plus';import { api } from '../api';import { errorText,showApiError } from '../feedback'
const form=reactive<any>({});const loading=ref(false);const saving=ref(false);const credential=ref('');const error=ref('')
async function load(){loading.value=true;error.value='';try{Object.assign(form,await api('/settings'))}catch(reason){error.value=errorText(reason,'系统设置加载失败')}finally{loading.value=false}}
onMounted(load)
async function save(){if(saving.value)return;saving.value=true;try{const payload={...form};if(credential.value)payload.salt_api_credential=credential.value;delete payload.role_detection_rules;Object.assign(form,await api('/settings',{method:'PATCH',body:JSON.stringify(payload)}));credential.value='';ElMessage.success('系统设置已保存')}catch(reason){showApiError(reason,'系统设置保存失败')}finally{saving.value=false}}
</script>
<template><div class="page-head"><div><h1>系统设置</h1><p>仅管理 Automation Center 自身运行参数</p></div></div><el-alert v-if="error" :title="error" type="error" show-icon :closable="false"><el-button link @click="load">重试</el-button></el-alert><div class="two-column" v-loading="loading"><div class="panel"><div class="panel-title"><h2>Salt Settings</h2></div><el-form label-position="top"><el-form-item label="salt_api_url"><el-input v-model="form.salt_api_url" /></el-form-item><el-form-item label="salt_api_username"><el-input v-model="form.salt_api_username" /></el-form-item><el-form-item label="salt_api_credential"><el-input v-model="credential" type="password" :placeholder="form.salt_api_credential||'输入新凭据'" /></el-form-item><el-form-item label="request_timeout (1–300 秒)"><el-input-number v-model="form.salt_request_timeout" :min="1" :max="300" /></el-form-item></el-form></div><div class="panel"><div class="panel-title"><h2>Execution & Node</h2></div><el-form label-position="top"><el-form-item label="default_step_timeout (1–86400 秒)"><el-input-number v-model="form.default_step_timeout" :min="1" :max="86400" /></el-form-item><el-form-item label="execution_log_retention_days (1–365 天)"><el-input-number v-model="form.execution_log_retention_days" :min="1" :max="365" /></el-form-item><el-form-item label="node_status_check_interval (5–3600 秒)"><el-input-number v-model="form.node_status_check_interval" :min="5" :max="3600" /></el-form-item><el-form-item label="max_upload_size (bytes)"><el-input-number v-model="form.max_upload_size" :min="1048576" :max="10737418240" /></el-form-item><div class="form-actions"><el-button type="primary" :loading="saving" :disabled="loading||saving" @click="save">保存设置</el-button></div></el-form></div></div></template>
